// 9LMNTS Studio Lead Parser & Deposit Calculator
const item = $input.first().json;

const clientName = item.clientName || item.name || 'Anonymous Prospect';
const phone = item.phone || item.mobile || 'N/A';
const service = item.service || item.bottleneck || 'Modular Upgrade';
const businessName = item.businessName || item.company || 'Direct Prospect';
const sourceUrl = item.sourceUrl || item.url || '9lmntsstudio.com';
const notes = item.notes || item.headcount || 'Standard inquiry';

// Determine Package & 50% Kickoff Deposit Rail
let packageTier = 'Modular System Upgrade';
let totalQuote = 500;
let depositDue = 250;
let turnaround = '24–48 Hours';

if (service.toLowerCase().includes('recovery') || service.toLowerCase().includes('1500') || service.toLowerCase().includes('catering')) {
  packageTier = 'The Revenue Recovery System';
  totalQuote = 1500;
  depositDue = 750;
  turnaround = '3–5 Business Days';
} else if (service.toLowerCase().includes('os') || service.toLowerCase().includes('3000') || service.toLowerCase().includes('handyman') || service.toLowerCase().includes('reception')) {
  packageTier = 'The Turnkey Business OS';
  totalQuote = 3000;
  depositDue = 1500;
  turnaround = '2–3 Weeks';
} else if (service.toLowerCase().includes('enterprise') || service.toLowerCase().includes('5000')) {
  packageTier = 'The Enterprise Sprint';
  totalQuote = 5000;
  depositDue = 2500;
  turnaround = '3–4 Weeks';
}

const interacInstructions = `Interac e-Transfer to 9lmntstudio@gmail.com (Desjardins Corporate Account, Autodeposit Active, 0% fees). Due now: $${depositDue} CAD.`;
const formattedAlert = `⚡ [NEW 9LMNTS SPRINT ALERT]\nClient: ${clientName} (${businessName})\nPhone: ${phone}\nPackage: ${packageTier} ($${totalQuote} CAD)\n50% Deposit: $${depositDue} CAD\nTurnaround: ${turnaround}\nSource: ${sourceUrl}\nNotes: ${notes}`;

return [{
  json: {
    clientName,
    businessName,
    phone,
    service,
    packageTier,
    totalQuote,
    depositDue,
    turnaround,
    interacInstructions,
    formattedAlert,
    notes,
    sourceUrl,
    timestamp: new Date().toISOString()
  }
}];

